        image_size: vfResolutionToSize(offer.resolution) || params.image_size || undefined,
        num_images: Math.max(1, Math.floor(vfNum(params.num_images) || 1)),
        quality: params.quality || 'high',
        output_format: params.output_format || 'png',
      });
    },
  },
  'fal-ai/flux-2-max': {
    modes: ['text_to_image'],
    validate: (job) => (job.prompt ? null : 'PROMPT_REQUIRED'),
    body(job, params) {
      return vfCompact({
        prompt: job.prompt,
        image_size: params.image_size || 'landscape_16_9',
        output_format: params.output_format || 'png',
        seed: vfNum(params.seed) == null ? undefined : vfNum(params.seed),
      });
    },
  },
  'fal-ai/flux-2-max/edit': {
    modes: ['image_edit'],
    validate(job, params, inputs) {
      if (!job.prompt) return 'PROMPT_REQUIRED';
      if (!vfInputsByRole(inputs, 'edit_source').concat(vfInputsByRole(inputs, 'reference')).length) return 'EDIT_SOURCE_REQUIRED';
      return null;
    },
    body(job, params, inputs) {
      return vfCompact({
        prompt: job.prompt,
        image_urls: vfInputsByRole(inputs, 'edit_source').concat(vfInputsByRole(inputs, 'reference')),
        image_size: params.image_size || 'auto',
        output_format: params.output_format || 'png',
        seed: vfNum(params.seed) == null ? undefined : vfNum(params.seed),
      });
    },
  },
  'fal-ai/veo3.1': { modes: ['text_to_video'], validate: vfFalVeoValidate, body: vfFalVeoBody },
  'fal-ai/veo3.1/fast': { modes: ['text_to_video'], validate: vfFalVeoValidate, body: vfFalVeoBody },
  'fal-ai/elevenlabs/tts/multilingual-v2': {
    modes: ['tts'],
    validate(job, params) {
      if (!job.prompt) return 'TEXT_REQUIRED';
      // Brand narration must pin a voice; never fall back to the provider default voice.
      if (!params.voice) return 'VOICE_REQUIRED';
      return null;
    },
    body(job, params) {
      return vfCompact({
        text: job.prompt,
        voice: params.voice,
        stability: vfNum(params.stability) == null ? undefined : vfNum(params.stability),
        similarity_boost: vfNum(params.similarity_boost) == null ? undefined : vfNum(params.similarity_boost),
        style: vfNum(params.style) == null ? undefined : vfNum(params.style),
        speed: vfNum(params.speed) == null ? undefined : vfNum(params.speed),
        language_code: params.language_code || undefined,
      });
    },
  },
};

function vfFalMinimaxValidate(needsImage) {
  return function (job, params, inputs) {
    if (!job.prompt) return 'PROMPT_REQUIRED';
    if (needsImage && !vfInputsByRole(inputs, 'start_frame').length) return 'START_FRAME_REQUIRED';
    if (!vfIntInRange(vfRequestedDuration(params), 1, 15)) return 'DURATION_UNSUPPORTED_1_TO_15_INTEGER_SECONDS';
    return null;
  };
}

function vfFalMinimaxBody(withImage) {
  return function (job, params, inputs, offer) {
    const body = {
      prompt: job.prompt,
      prompt_expansion_mode: params.prompt_expansion_mode || 'balanced',
      duration: vfRequestedDuration(params),
      // fal's MiniMax enum is upper-case (480P | 768P | 1080P).
      resolution: String(offer.resolution || params.resolution || '768p').toUpperCase(),
      seed: vfNum(params.seed) == null ? undefined : vfNum(params.seed),
    };
    if (withImage) {
      body.image_url = vfInputsByRole(inputs, 'start_frame')[0];
      body.end_image_url = vfInputsByRole(inputs, 'end_frame')[0];
    } else {
      body.aspect_ratio = params.aspect_ratio || '16:9';
    }
    return vfCompact(body);
  };
}

function vfFalVeoValidate(job, params) {
  if (!job.prompt) return 'PROMPT_REQUIRED';
  if (![4, 6, 8].includes(vfRequestedDuration(params))) return 'DURATION_UNSUPPORTED_4_6_8_SECONDS';
  return null;
}

function vfFalVeoBody(job, params, inputs, offer) {
  return vfCompact({
    prompt: job.prompt,
    negative_prompt: job.negative_prompt || undefined,
    duration: vfRequestedDuration(params) + 's',
    resolution: String(offer.resolution || '720p').toLowerCase(),
    aspect_ratio: params.aspect_ratio === '9:16' ? '9:16' : '16:9',
    generate_audio: offer.audio_included === true,
  });
}

function vfFalSupports(offer, job, mode, params, inputs) {
  const mapper = VF_FAL_MAPPERS[offer.provider_model_key];
  if (!mapper) return 'ADAPTER_MAPPING_NOT_IMPLEMENTED';
  if (!mapper.modes.includes(mode)) return 'MODE_MISMATCH';
  return mapper.validate(job, params, inputs, offer);
}

function vfFalBuildRequest(offer, job, params, inputs) {
  const mapper = VF_FAL_MAPPERS[offer.provider_model_key];
  const path = vfFalQueuePath(offer);
  return {
    method: 'POST',
    url: VF_FAL_QUEUE_BASE + '/' + path,
    body: mapper.body(job, params, inputs, offer),
    queue_path: path,
  };
}

const VF_FAL_STATUS_MAP = { IN_QUEUE: 'PENDING', IN_PROGRESS: 'RUNNING', COMPLETED: 'COMPLETED' };

function vfFalDetail(body) {
  if (!body) return '';
  if (typeof body === 'string') return vfTruncate(body, 400);
  const d = body.detail || body.error || body.message;
  return vfTruncate(typeof d === 'string' ? d : JSON.stringify(d || body), 400);
}

function vfFalNormalizeSubmit(http) {
  if (!http.transport_ok) {
    return { accepted: false, provider_job_id: null, status: 'FAILED', error: 'fal submit transport error: ' + http.transport_error, raw_response: null, retryable: true };
  }
  const b = http.body || {};
  if (http.status_code >= 200 && http.status_code < 300 && b.request_id) {
    return {
      accepted: true,
      provider_job_id: String(b.request_id),
      status: VF_FAL_STATUS_MAP[b.status] === 'RUNNING' ? 'RUNNING' : 'PENDING',
      error: null,
      raw_response: vfSafeRaw(b),
      poll: { status_url: b.status_url || null, response_url: b.response_url || null, cancel_url: b.cancel_url || null },
    };
  }
  return {
    accepted: false,
    provider_job_id: null,
    status: 'FAILED',
    error: 'fal submit HTTP ' + http.status_code + ': ' + vfFalDetail(b),
    raw_response: vfSafeRaw(b),
  };
}

function vfFalStatusRequest(attempt, offer) {
  const submit = (attempt.response_payload && attempt.response_payload.submit) || {};
  const poll = submit.poll || {};
  const base = VF_FAL_QUEUE_BASE + '/' + ((attempt.request_payload && attempt.request_payload.provider_request && attempt.request_payload.provider_request.queue_path) || vfFalQueuePath(offer));
  return {
    method: 'GET',
    url: poll.status_url || base + '/requests/' + attempt.external_job_id + '/status',
    response_url: poll.response_url || base + '/requests/' + attempt.external_job_id,
  };
}

// Poll step 1: queue status.
function vfFalNormalizeStatus(http) {
  if (!http.transport_ok) return { status: 'RUNNING', transient: true, error: 'fal status transport error: ' + http.transport_error, raw_response: null };
  const b = http.body || {};
  if (http.status_code === 401 || http.status_code === 403) {
    return { status: 'RUNNING', transient: true, error: 'fal status HTTP ' + http.status_code + ' (credential problem; job left waiting)', raw_response: vfSafeRaw(b) };
  }
  if (http.status_code >= 500 || http.status_code === 429) {
    return { status: 'RUNNING', transient: true, error: 'fal status HTTP ' + http.status_code, raw_response: vfSafeRaw(b) };
  }
  if (http.status_code >= 400) {
    return { status: 'FAILED', error: 'fal status HTTP ' + http.status_code + ': ' + vfFalDetail(b), raw_response: vfSafeRaw(b) };
  }
  const mapped = VF_FAL_STATUS_MAP[b.status];
  if (!mapped) return { status: 'RUNNING', transient: true, error: 'fal status unrecognized: ' + vfTruncate(b.status, 40), raw_response: vfSafeRaw(b) };
  if (mapped === 'COMPLETED') {
    if (b.error) return { status: 'FAILED', error: 'fal reported error: ' + vfTruncate(b.error, 400), raw_response: vfSafeRaw(b) };
    return { status: 'COMPLETED', needs_result_fetch: true, error: null, raw_response: vfSafeRaw(b) };
  }
  return { status: mapped, error: null, raw_response: vfSafeRaw(b) };
}

function vfFalCollectFiles(body) {
  const files = [];
  const push = (f) => {
    if (f && typeof f === 'object' && typeof f.url === 'string') {
      files.push({
        url: f.url,
        mime_type: f.content_type || null,
        size_bytes: vfNum(f.file_size),
        width: vfNum(f.width),
        height: vfNum(f.height),
        duration_seconds: vfNum(f.duration),
        file_name: f.file_name || null,
      });
    }
  };
  if (!body || typeof body !== 'object') return files;
  push(body.video);
  push(body.audio);
  push(body.image);
  for (const img of Array.isArray(body.images) ? body.images : []) push(img);
  return files;
}

// Poll step 2: result payload once the queue reports COMPLETED.
function vfFalNormalizeResult(http) {
  if (!http.transport_ok) return { status: 'RUNNING', transient: true, error: 'fal result transport error: ' + http.transport_error, raw_response: null, result_urls: [], files: [] };
  const b = http.body || {};
  if (http.status_code >= 500 || http.status_code === 429 || http.status_code === 401 || http.status_code === 403) {
    return { status: 'RUNNING', transient: true, error: 'fal result HTTP ' + http.status_code, raw_response: vfSafeRaw(b), result_urls: [], files: [] };
  }
  if (http.status_code >= 400) {
    return { status: 'FAILED', error: 'fal result HTTP ' + http.status_code + ': ' + vfFalDetail(b), raw_response: vfSafeRaw(b), result_urls: [], files: [] };
  }
  const files = vfFalCollectFiles(b);
  if (!files.length) {
    return { status: 'FAILED', error: 'fal result contained no output files', raw_response: vfSafeRaw(b), result_urls: [], files: [] };
  }
  return { status: 'SUCCEEDED', error: null, raw_response: vfSafeRaw(b), result_urls: files.map((f) => f.url), files, credits_consumed: null };
}

// Kie adapter (Market jobs API).
//
// Submit: POST https://api.kie.ai/api/v1/jobs/createTask  { model, input } -> { code, msg, data: { taskId } }
// Poll  : GET  https://api.kie.ai/api/v1/jobs/recordInfo?taskId=...        -> { code, data: { state, resultJson, failCode, failMsg, creditsConsumed } }
//
// Input fields were taken from docs.kie.ai market pages on 2026-09-17. Kie
// returns credits, not USD; credits are recorded but never converted to a
// price without a verified rate.

const VF_KIE_BASE = 'https://api.kie.ai';

const VF_KIE_MAPPERS = {
  'kling-3.0/video': {
    modes: ['text_to_video', 'image_to_video'],
    validate(job, params) {
      if (!job.prompt) return 'PROMPT_REQUIRED';
      if (!vfIntInRange(vfRequestedDuration(params), 3, 15)) return 'DURATION_UNSUPPORTED_3_TO_15_INTEGER_SECONDS';
      if (params.aspect_ratio && !['16:9', '9:16', '1:1'].includes(params.aspect_ratio)) return 'ASPECT_RATIO_UNSUPPORTED';
      return null;
    },
    body(job, params, inputs, offer) {
      const frames = vfInputsByRole(inputs, 'start_frame').slice(0, 1).concat(vfInputsByRole(inputs, 'end_frame').slice(0, 1));
      return {
        model: offer.provider_model_key,
        input: vfCompact({
          prompt: job.prompt,
          image_urls: frames.length ? frames : undefined,
          sound: offer.audio_included === true,
          duration: String(vfRequestedDuration(params)),
          aspect_ratio: params.aspect_ratio || '16:9',
          mode: params.kling_mode || 'pro',
          multi_shots: false,
        }),
      };
    },
  },
  'bytedance/seedance-2-5': {
    modes: ['text_to_video', 'image_to_video', 'reference_to_video'],
    validate(job, params) {
      if (!job.prompt) return 'PROMPT_REQUIRED';
      if (!vfIntInRange(vfRequestedDuration(params), 4, 30)) return 'DURATION_UNSUPPORTED_4_TO_30_INTEGER_SECONDS';
      return null;
    },
    body(job, params, inputs, offer) {
      return {
        model: offer.provider_model_key,
        input: vfCompact({
          prompt: job.prompt,
          first_frame_url: vfInputsByRole(inputs, 'start_frame')[0],
          last_frame_url: vfInputsByRole(inputs, 'end_frame')[0],
          reference_image_urls: vfInputsByRole(inputs, 'reference').concat(vfInputsByRole(inputs, 'reference_image')),
          reference_video_urls: vfInputsByRole(inputs, 'reference_video'),
          reference_audio_urls: vfInputsByRole(inputs, 'reference_audio'),
          generate_audio: offer.audio_included === true,
          resolution: String(offer.resolution || params.resolution || '720p').toLowerCase(),
          aspect_ratio: params.aspect_ratio || 'adaptive',
          duration: vfRequestedDuration(params),
        }),
      };
    },
  },
  'gpt-image-2-5-sunburst-text-to-image': {
    modes: ['text_to_image'],
    validate: (job) => (job.prompt ? null : 'PROMPT_REQUIRED'),
    body(job, params, inputs, offer) {
      return {
        model: offer.provider_model_key,
        input: vfCompact({ prompt: job.prompt, aspect_ratio: params.aspect_ratio || '16:9', resolution: offer.resolution || '2K' }),
      };
    },
  },
  'gpt-image-2-5-sunburst-image-to-image': {
    modes: ['image_edit'],
    validate(job, params, inputs) {
      if (!job.prompt) return 'PROMPT_REQUIRED';
      if (!vfInputsByRole(inputs, 'edit_source').concat(vfInputsByRole(inputs, 'reference')).length) return 'EDIT_SOURCE_REQUIRED';
      return null;
    },
    body(job, params, inputs, offer) {
      return {
        model: offer.provider_model_key,
        input: vfCompact({
          prompt: job.prompt,
          input_urls: vfInputsByRole(inputs, 'edit_source').concat(vfInputsByRole(inputs, 'reference')),
          aspect_ratio: params.aspect_ratio || 'auto',
          resolution: offer.resolution || '2K',
        }),
      };
    },
  },
  // Not mapped in v1 (routing records ADAPTER_MAPPING_NOT_IMPLEMENTED):
  //  - veo-3-1: Kie serves Veo from a dedicated API, not jobs/createTask.
  //  - elevenlabs/text-to-speech-multilingual-v2: Kie uses its own voice-id catalogue.
  //  - minimax-h3/text-to-video: unrouted alternative model.
};

function vfKieSupports(offer, job, mode, params, inputs) {
  const mapper = VF_KIE_MAPPERS[offer.provider_model_key];
  if (!mapper) return 'ADAPTER_MAPPING_NOT_IMPLEMENTED';
  if (!mapper.modes.includes(mode)) return 'MODE_MISMATCH';
  return mapper.validate(job, params, inputs, offer);
}

function vfKieBuildRequest(offer, job, params, inputs) {
  return {
    method: 'POST',
    url: VF_KIE_BASE + '/api/v1/jobs/createTask',
    body: VF_KIE_MAPPERS[offer.provider_model_key].body(job, params, inputs, offer),
  };
}

function vfKieNormalizeSubmit(http) {
  if (!http.transport_ok) {
    return { accepted: false, provider_job_id: null, status: 'FAILED', error: 'Kie submit transport error: ' + http.transport_error, raw_response: null };
  }
  const b = http.body || {};
  const taskId = b.data && b.data.taskId;
  if (http.status_code >= 200 && http.status_code < 300 && Number(b.code) === 200 && taskId) {
    return { accepted: true, provider_job_id: String(taskId), status: 'PENDING', error: null, raw_response: vfSafeRaw(b), poll: {} };
  }
  const code = b.code != null ? b.code : http.status_code;
  const label = { 401: 'unauthorized', 402: 'insufficient credits', 422: 'validation error', 429: 'rate limited', 455: 'maintenance', 501: 'generation failed', 505: 'feature disabled' }[Number(code)] || 'error';
  return {
    accepted: false,
    provider_job_id: null,
    status: 'FAILED',
    error: 'Kie submit code ' + code + ' (' + label + '): ' + vfTruncate(b.msg || '', 300),
    raw_response: vfSafeRaw(b),
  };
}

function vfKieStatusRequest(attempt) {
  return { method: 'GET', url: VF_KIE_BASE + '/api/v1/jobs/recordInfo?taskId=' + encodeURIComponent(attempt.external_job_id) };
}

const VF_KIE_TASK_STATES = ['waiting', 'queuing', 'generating', 'success', 'fail'];
// Codes that mean "ask again later" rather than "this task is broken".
const VF_KIE_TRANSIENT_CODES = [429, 455, 500];

function vfKieNormalizePoll(http) {
  if (!http.transport_ok) return { status: 'RUNNING', transient: true, error: 'Kie poll transport error: ' + http.transport_error, raw_response: null, result_urls: [], files: [] };
  const b = http.body || {};
  const code = Number(b.code != null ? b.code : http.status_code);
  const transient = (reason) => ({ status: 'RUNNING', transient: true, error: reason, raw_response: vfSafeRaw(b), result_urls: [], files: [] });

  // 1. Transport/status level first: these say nothing about the task itself.
  if (http.status_code === 401 || http.status_code === 403 || http.status_code === 429 || http.status_code >= 500) {
    return transient('Kie poll HTTP ' + http.status_code);
  }
  const d = b.data;
  const hasState = Boolean(d) && VF_KIE_TASK_STATES.includes(d.state);
  if (http.status_code >= 400 && !hasState) {
    return { status: 'FAILED', error: 'Kie poll HTTP ' + http.status_code + ': ' + vfTruncate(b.msg || '', 300), raw_response: vfSafeRaw(b), result_urls: [], files: [] };
  }

  // 2. On a 2xx response a valid task state is authoritative: Kie returns
  //    envelope codes such as 505 alongside a completed task (see its
  //    get-task-detail docs), so the state must win over body.code.
  if (!hasState) {
    if (VF_KIE_TRANSIENT_CODES.includes(code)) return transient('Kie poll code ' + code + ': ' + vfTruncate(b.msg || '', 200));
    if (d && d.state != null) return transient('Kie state unrecognized: ' + vfTruncate(d.state, 40));
    return { status: 'FAILED', error: 'Kie poll returned no task state (code ' + code + '): ' + vfTruncate(b.msg || '', 300), raw_response: vfSafeRaw(b), result_urls: [], files: [] };
  }

  const credits = vfNum(d.creditsConsumed);
  switch (d.state) {
    case 'waiting':
    case 'queuing':
      return { status: 'PENDING', error: null, raw_response: vfSafeRaw(b), result_urls: [], files: [], credits_consumed: credits };
    case 'generating':
      return { status: 'RUNNING', error: null, raw_response: vfSafeRaw(b), result_urls: [], files: [], credits_consumed: credits };
    case 'success': {
      let parsed = d.resultJson;
      if (typeof parsed === 'string') {
        try { parsed = JSON.parse(parsed); } catch (e) { parsed = null; }
      }
      const urls = parsed && Array.isArray(parsed.resultUrls) ? parsed.resultUrls.filter((u) => typeof u === 'string') : [];
      if (!urls.length) return { status: 'FAILED', error: 'Kie task succeeded without resultUrls', raw_response: vfSafeRaw(b), result_urls: [], files: [], credits_consumed: credits };
      return {
        status: 'SUCCEEDED',
        error: null,
        raw_response: vfSafeRaw(b),
        result_urls: urls,
        files: urls.map((u) => ({ url: u, mime_type: null, size_bytes: null, width: null, height: null, duration_seconds: null, file_name: null })),
        credits_consumed: credits,
      };
    }
    default: // 'fail'
      return { status: 'FAILED', error: 'Kie task failed: ' + vfTruncate((d.failCode || '') + ' ' + (d.failMsg || ''), 400).trim(), raw_response: vfSafeRaw(b), result_urls: [], files: [], credits_consumed: credits };
  }
}

// Quality-first route selection. Model first, provider second.
//
// Selection order (never reordered for cost):
//   1. quality threshold    - enforced by get_route_candidates (quality_tier >= profile minimum)
//   2. capability match     - required mode, adapter mapping, request constraints, adapter active
//   3. provider reliability - within the chosen model only
//   4. effective price      - within the chosen model only; unknown price ranks after known price
//   5. latency              - within the chosen model only
//
// A lower-priority model is considered only when every offer of every
// higher-priority model is ineligible for a recorded, non-price reason.

const VF_SELECTION_ORDER = ['quality_threshold', 'capability_match', 'provider_reliability', 'effective_price', 'latency'];

const VF_MODE_COMPAT = {
  text_to_image: ['text_to_image'],
  image_edit: ['image_edit', 'image_to_image'],
  text_to_video: ['text_to_video', 'video', 'multimodal_video'],
  image_to_video: ['image_to_video', 'video', 'multimodal_video'],
  reference_to_video: ['reference_to_video', 'multimodal_video'],
  tts: ['tts'],
};

const VF_PROVIDER_ADAPTERS = {
  fal: { supports: vfFalSupports, buildRequest: vfFalBuildRequest },
  kie: { supports: vfKieSupports, buildRequest: vfKieBuildRequest },
};

function vfRequiredMode(job, inputs) {
  const roles = new Set(inputs.filter((i) => i.uri).map((i) => i.role));
  switch (job.job_kind) {
    case 'IMAGE':
      return roles.has('edit_source') || roles.has('reference') ? 'image_edit' : 'text_to_image';
    case 'VIDEO':
      if (roles.has('start_frame')) return 'image_to_video';
      if (roles.has('reference') || roles.has('reference_image') || roles.has('reference_video')) return 'reference_to_video';
      return 'text_to_video';
    case 'TTS':
      return 'tts';
    default:
      return null;
  }
}

function vfOfferRankKey(o) {
  const price = vfNum(o.unit_price);
  return [
    -(vfNum(o.reliability_score) == null ? -1 : vfNum(o.reliability_score)), // reliability desc, unknown last
    price == null ? 1 : 0, // known price before unknown price
    price == null ? 0 : price, // price asc
    -(vfNum(o.latency_score) == null ? -1 : vfNum(o.latency_score)), // latency desc, unknown last
    String(o.provider_slug || ''),
  ];
}

function vfCompareKeys(a, b) {
  for (let i = 0; i < a.length; i++) {
    if (a[i] < b[i]) return -1;
    if (a[i] > b[i]) return 1;
  }
  return 0;
}

// ctx: the "Load Routing Context" row plus worker_id.
function vfSelectRoute(ctx) {
  const job = ctx.job;
  const req = ctx.requirements || {};
  const profile = ctx.profile;
  const adapters = ctx.adapters || {};
  const inputs = vfResolveInputs(job, ctx.input_assets);
  const params = vfEffectiveParameters(job, ctx.shot);
  const mode = vfRequiredMode(job, inputs);
  const failedOffers = new Set(ctx.failed_offer_ids || []);
  const excludedModels = new Set(Array.isArray(params.exclude_canonical_models) ? params.exclude_canonical_models : []);

  const decision = {
    contract_version: VF_CONTRACT_VERSION,
    strategy: 'QUALITY_FIRST',
    selection_order: VF_SELECTION_ORDER,
    decided_at: new Date().toISOString(),
    decided_by: ctx.worker_id,
    profile_slug: profile ? profile.slug : null,
    routing_class: req.routing_class || null,
    constraints: {
      required_mode: mode,
      resolution: req.resolution || null,
      audio_included: req.audio_included == null ? null : req.audio_included,
      premium_exception_approved: req.premium_approved === true,
      minimum_quality_tier: profile ? profile.minimum_quality_tier : null,
    },
    model_evaluation: [],
    selected: null,
  };

  const fail = (reason) => {
    decision.outcome = 'NO_ELIGIBLE_ROUTE';
    decision.failure_reason = reason;
    return { outcome: 'NO_ROUTE', error: 'NO_ELIGIBLE_ROUTE: ' + reason, decision };
  };

  if (!profile) return fail('ROUTING_PROFILE_NOT_FOUND');
  if (!req.routing_class) return fail('ROUTING_CLASS_MISSING');
  if (!mode) return fail('JOB_KIND_NOT_ROUTABLE_' + job.job_kind);

  const candidates = Array.isArray(ctx.candidates) ? ctx.candidates : [];
  if (!candidates.length) return fail('NO_ROUTING_RULES_FOR_CLASS');

  // Group by routing rule, preserving rule priority (the quality order).
  const groups = [];
  const byRule = {};
  for (const c of candidates) {
    const key = c.routing_rule_id;
    if (!byRule[key]) {
      byRule[key] = { rule_priority: c.rule_priority, rule_role: c.rule_role, canonical_model_id: c.canonical_model_id, canonical_model_slug: c.canonical_model_slug, quality_tier: c.quality_tier, offers: [] };
      groups.push(byRule[key]);
    }
    if (c.provider_offer_id) byRule[key].offers.push(c);
  }
  groups.sort((a, b) => a.rule_priority - b.rule_priority);

  let selected = null;
  for (const g of groups) {
    const evaluation = { rule_priority: g.rule_priority, rule_role: g.rule_role, canonical_model_slug: g.canonical_model_slug, quality_tier: g.quality_tier, offers: [] };
    decision.model_evaluation.push(evaluation);

    if (selected) {
      evaluation.outcome = 'NOT_EVALUATED';
      evaluation.reason = 'HIGHER_PRIORITY_MODEL_SELECTED';
      continue;
    }
    if (excludedModels.has(g.canonical_model_slug)) {
      evaluation.outcome = 'REJECTED';
      evaluation.reason = 'EXCLUDED_BY_QUALITY_GATE';
      continue;
    }

    const eligible = [];
    for (const o of g.offers) {
      let reason = null;
      const adapter = adapters[o.provider_slug];
      const impl = VF_PROVIDER_ADAPTERS[o.provider_slug];
      const offerMode = (o.offer_capabilities && o.offer_capabilities.mode) || null;
      if (!impl) reason = 'PROVIDER_NOT_A_PRODUCTION_ADAPTER';
      else if (!(VF_MODE_COMPAT[mode] || []).includes(offerMode)) reason = 'MODE_MISMATCH';
      else if (!adapter || adapter.provider_active !== true) reason = 'PROVIDER_INACTIVE';
      else if (adapter.adapter_active !== true) reason = 'ADAPTER_INACTIVE';
      else if (failedOffers.has(o.provider_offer_id)) reason = 'PREVIOUS_ATTEMPT_FAILED';
      else reason = impl.supports(o, job, mode, params, inputs);
      evaluation.offers.push({
        provider_offer_id: o.provider_offer_id,
        provider_slug: o.provider_slug,
        provider_model_key: o.provider_model_key,
        unit_price: vfNum(o.unit_price),
        pricing_basis: o.pricing_basis,
        outcome: reason ? 'REJECTED' : 'ELIGIBLE',
        reason,
      });
      if (!reason) eligible.push(o);
    }

    if (!g.offers.length) {
      evaluation.outcome = 'REJECTED';
      evaluation.reason = 'NO_ACTIVE_OFFER_FOR_CONSTRAINTS';
    } else if (!eligible.length) {
      evaluation.outcome = 'REJECTED';
      evaluation.reason = 'NO_CAPABLE_PROVIDER_OFFER';
    } else {
      // Provider second: reliability, then effective price, then latency - within this model only.
      eligible.sort((a, b) => vfCompareKeys(vfOfferRankKey(a), vfOfferRankKey(b)));
      selected = eligible[0];
      evaluation.outcome = 'SELECTED';
      for (const e of evaluation.offers) {
        if (e.provider_offer_id === selected.provider_offer_id) e.outcome = 'SELECTED';
        else if (e.outcome === 'ELIGIBLE') e.reason = 'RANKED_BELOW_SELECTED_OFFER';
      }
    }

    if (!selected && profile.allow_model_fallback === false) break;
  }

  if (!selected) return fail('NO_CAPABLE_OFFER_FOR_ANY_ALLOWED_MODEL');

  const estimate = vfEstimateCost(selected, job, params);
  decision.outcome = 'ROUTED';
  decision.selected = {
    rule_priority: selected.rule_priority,
    rule_role: selected.rule_role,
    canonical_model_id: selected.canonical_model_id,
    canonical_model_slug: selected.canonical_model_slug,
    provider_offer_id: selected.provider_offer_id,
    provider_id: selected.provider_id,
    provider_slug: selected.provider_slug,
    provider_model_key: selected.provider_model_key,
    pricing_basis: selected.pricing_basis,
    unit_price: vfNum(selected.unit_price),
    currency: selected.currency,
    resolution: selected.resolution,
    audio_included: selected.audio_included,
    promotion_name: selected.promotion_name,
  };
  decision.cost_estimate = estimate;

  return { outcome: 'ROUTED', decision, selected, estimate, mode, params, inputs };
}

// Durable storage abstraction for asset archival.
//
// A backend maps a Video Factory asset to one deterministic object and knows how
// to build the upload request and read the response. The runtime never hard-wires
// a single vendor: the active backend comes from config/factory-manifest.json
// (storage.backend), inlined into the workflow at build time.
//
// Credentials are never part of these objects; the HTTP node carries an n8n
// credential (VIDEO_FACTORY_SUPABASE_STORAGE for the Supabase backend).

const VF_STORAGE_CONTRACT_VERSION = '1.0';

const VF_EXT_BY_MIME = {
  'video/mp4': 'mp4',
  'video/quicktime': 'mov',
  'video/webm': 'webm',
  'image/png': 'png',
  'image/jpeg': 'jpg',
  'image/webp': 'webp',
  'audio/mpeg': 'mp3',
  'audio/wav': 'wav',
};

function vfObjectExtension(asset) {
  const fromUri = /\.([a-z0-9]{2,4})(?:\?|$)/i.exec(String(asset.uri || '').split('?')[0]);
  if (fromUri) return fromUri[1].toLowerCase();
  return VF_EXT_BY_MIME[asset.mime_type] || 'bin';
}

// Deterministic: the same asset always maps to the same object, so a retry
// overwrites in place instead of creating a second archive object.
function vfObjectKey(asset, template) {
  const ext = vfObjectExtension(asset);
  return String(template || 'episodes/{episode_id}/assets/{asset_id}.{ext}')
    .replace('{episode_id}', asset.episode_id || 'unassigned')
    .replace('{asset_id}', asset.id)
    .replace('{asset_type}', String(asset.asset_type || 'other').toLowerCase())
    .replace('{ext}', ext);
}

const VF_STORAGE_BACKENDS = {
  // Supabase Storage: existing Video Factory infrastructure, no new paid service.
  supabase_storage: {
    buildUpload(asset, key, cfg) {
      const base = String(cfg.base_url || '').replace(/\/$/, '');
      if (!base) return { error: 'STORAGE_BASE_URL_NOT_CONFIGURED' };
      if (!cfg.bucket) return { error: 'STORAGE_BUCKET_NOT_CONFIGURED' };
      return {
        method: 'POST',
        url: `${base}/storage/v1/object/${cfg.bucket}/${key}`,
        headers: {
          // upsert keeps archival idempotent for a retried asset
          'x-upsert': 'true',
          'cache-control': String(cfg.cache_control || 'max-age=31536000'),
          'content-type': asset.mime_type || 'application/octet-stream',
        },
      };
    },
    normalizeUpload(http, asset, key, cfg) {
      if (!http.transport_ok) return { ok: false, retryable: true, error: 'storage upload transport error: ' + http.transport_error };
      if (http.status_code === 401 || http.status_code === 403) return { ok: false, retryable: true, error: 'storage upload unauthorized (HTTP ' + http.status_code + ')' };
      if (http.status_code >= 500 || http.status_code === 429) return { ok: false, retryable: true, error: 'storage upload HTTP ' + http.status_code };
      if (http.status_code < 200 || http.status_code >= 300) {
        const b = http.body || {};
        return { ok: false, retryable: false, error: 'storage upload HTTP ' + http.status_code + ': ' + vfTruncate(typeof b === 'string' ? b : (b.message || b.error || JSON.stringify(b)), 300) };
      }
      const base = String(cfg.base_url || '').replace(/\/$/, '');
      const uri = cfg.public_read
        ? `${base}/storage/v1/object/public/${cfg.bucket}/${key}`
        : `${base}/storage/v1/object/${cfg.bucket}/${key}`;
      const body = http.body && typeof http.body === 'object' ? http.body : {};
      const h = http.headers || {};
      const etag = h.etag || h.ETag || body.Etag || body.etag || null;
      return {
        ok: true,
        archive_uri: uri,
        archive_object_key: key,
        archive_storage_provider: 'supabase_storage',
        // Supabase returns an ETag for the stored object; it is the only integrity
        // value available without hashing the payload inside the workflow sandbox.
        checksum: etag ? String(etag).replace(/"/g, '') : null,
        checksum_algorithm: etag ? 'etag' : null,
      };
    },
  },
};

function vfStorageBackend(cfg) {
  return VF_STORAGE_BACKENDS[(cfg && cfg.backend) || ''] || null;
}

// "Claim Asset For Archive" -> archive request, or a terminal reason not to archive.
// defaults come from config/factory-manifest.json at build time; the database row
// (providers.supabase_storage) supplies base_url/bucket and is authoritative.
function vfStepBuildArchive(row, workerId, defaults) {
  if (!row || !row.asset || !row.asset.id) return { outcome: 'NO_ASSET' };
  const asset = row.asset;
  const cfg = Object.assign({}, defaults || {}, row.storage_config || {});
  const base = { worker_id: workerId, asset_id: asset.id, provider_uri: asset.uri, mime_type: asset.mime_type || null };

  const backend = vfStorageBackend(cfg);
  if (!backend) {
    return Object.assign(base, { outcome: 'FAILED', fail_payload: { asset_id: asset.id, worker_id: workerId, stage: 'configure', error: 'STORAGE_BACKEND_NOT_CONFIGURED: ' + ((cfg && cfg.backend) || 'none') } });
  }
  if (!asset.uri || !/^https:\/\//i.test(asset.uri)) {
    return Object.assign(base, { outcome: 'FAILED', fail_payload: { asset_id: asset.id, worker_id: workerId, stage: 'configure', error: 'ASSET_URI_NOT_ARCHIVABLE' } });
  }
  if (asset.archive_uri) {
    return Object.assign(base, { outcome: 'ALREADY_ARCHIVED' });
  }

  const key = vfObjectKey(asset, cfg.path_template);
  const upload = backend.buildUpload(asset, key, cfg);
  if (upload.error) {
    return Object.assign(base, { outcome: 'FAILED', fail_payload: { asset_id: asset.id, worker_id: workerId, stage: 'configure', error: upload.error } });
  }
  return Object.assign(base, {
    outcome: 'ARCHIVE',
    contract_version: VF_STORAGE_CONTRACT_VERSION,
    storage_config: cfg,
    object_key: key,
    download_request: { method: 'GET', url: asset.uri },
    upload_request: upload,
  });
}

function vfStepAfterDownload(plan, httpItem, binaryMeta) {
  const http = vfHttpResult(httpItem);
  if (!http.transport_ok) {
    return Object.assign({}, plan, { outcome: 'FAILED', fail_payload: { asset_id: plan.asset_id, worker_id: plan.worker_id, stage: 'download', error: 'provider download transport error: ' + http.transport_error } });
  }
  if (http.status_code < 200 || http.status_code >= 300) {
    return Object.assign({}, plan, { outcome: 'FAILED', fail_payload: { asset_id: plan.asset_id, worker_id: plan.worker_id, stage: 'download', error: 'provider download HTTP ' + http.status_code } });
  }
  const size = binaryMeta && (binaryMeta.fileSize != null ? Number(binaryMeta.fileSize) : null);
  return Object.assign({}, plan, { outcome: 'UPLOAD', downloaded: { size_bytes: Number.isFinite(size) ? size : null, mime_type: (binaryMeta && binaryMeta.mimeType) || plan.mime_type } });
}

function vfStepAfterUpload(plan, httpItem, cfg) {
  const http = vfHttpResult(httpItem);
  const backend = vfStorageBackend(cfg);
  const res = backend.normalizeUpload(http, { id: plan.asset_id, mime_type: plan.mime_type }, plan.object_key, cfg);
  if (!res.ok) {
    return Object.assign({}, plan, { outcome: 'FAILED', fail_payload: { asset_id: plan.asset_id, worker_id: plan.worker_id, stage: 'upload', error: res.error } });
  }
  return Object.assign({}, plan, {
    outcome: 'ARCHIVED',
    persist_payload: {
      asset_id: plan.asset_id,
      worker_id: plan.worker_id,
      archive_uri: res.archive_uri,
      archive_object_key: res.archive_object_key,
      archive_storage_provider: res.archive_storage_provider,
      archive_checksum: res.checksum,
      archive_checksum_algorithm: res.checksum_algorithm,
      archive_size_bytes: (plan.downloaded && plan.downloaded.size_bytes) || null,
    },
  });
}

// Step functions used by the n8n Code nodes of
//   VF - Generation Worker v1
//   VF - Provider Poll v1
// Each takes plain JSON and returns plain JSON so that the identical text can
// run inside n8n and inside scripts/test-runtime.mjs.

const VF_SUBMIT_NORMALIZERS = { fal: vfFalNormalizeSubmit, kie: vfKieNormalizeSubmit };

// ---------------------------------------------------------------------------
// Generation Worker
// ---------------------------------------------------------------------------

// "Select Quality-First Route": ctx = Load Routing Context row.
function vfStepSelectRoute(ctx, workerId) {
  if (!ctx || !ctx.job || !ctx.job.id) {
    return { outcome: 'LEASE_LOST', worker_id: workerId };
  }
  const route = vfSelectRoute(Object.assign({}, ctx, { worker_id: workerId }));
  const base = { worker_id: workerId, job_id: ctx.job.id };
  if (route.outcome !== 'ROUTED') {
    return Object.assign(base, {
      outcome: 'NO_ROUTE',
      fail_payload: vfFailPayload({ job_id: ctx.job.id, worker_id: workerId, attempt_id: null, error: route.error, stage: 'route', routing_decision: route.decision }),
    });
  }
  return Object.assign(base, { outcome: 'ROUTED', route, job: ctx.job });
}

// "Normalize Provider Request": plan = output of vfStepSelectRoute.
function vfStepNormalizeRequest(plan) {
  const { route, job } = plan;
  const s = route.selected;
  const impl = VF_PROVIDER_ADAPTERS[s.provider_slug];
  let providerRequest;
  try {
    providerRequest = impl.buildRequest(s, job, route.params, route.inputs);
  } catch (e) {
    return Object.assign({}, plan, {
      outcome: 'INVALID',
      fail_payload: vfFailPayload({ job_id: job.id, worker_id: plan.worker_id, attempt_id: null, error: 'REQUEST_NORMALIZATION_FAILED: ' + vfTruncate(e && e.message, 300), stage: 'normalize_request' }),
    });
  }

  // Normalized submit input (contract v1). Stored on the attempt; contains no credentials.
  const submitInput = {
    contract_version: VF_CONTRACT_VERSION,
    provider_slug: s.provider_slug,
    provider_model_slug: s.provider_model_key,
    provider_model_offer_id: s.provider_offer_id,
    canonical_model_slug: s.canonical_model_slug,
    required_mode: route.mode,
    prompt: job.prompt || null,
    negative_prompt: job.negative_prompt || null,
    parameters: route.params,
    input_manifest: route.inputs,
    idempotency_key: job.idempotency_key || 'generation_job:' + job.id + ':attempt:' + job.attempts,
    provider_request: { method: providerRequest.method, url: providerRequest.url, body: providerRequest.body, queue_path: providerRequest.queue_path || null },
  };

  return {
    outcome: 'READY',
    worker_id: plan.worker_id,
    job_id: job.id,
    job_kind: job.job_kind,
    provider_slug: s.provider_slug,
    provider_request: providerRequest,
    estimate: route.estimate,
    lineage: vfLineageFor(route.inputs),
    persist_payload: {
      job_id: job.id,
      worker_id: plan.worker_id,
      canonical_model_id: s.canonical_model_id,
      provider_model_offer_id: s.provider_offer_id,
      routing_decision: route.decision,
      estimated_cost: route.estimate.amount,
      cost_estimate: route.estimate,
      currency: route.estimate.currency || 'USD',
      request_payload: submitInput,
    },
  };
}

// "Normalize Submit Result": request = Normalize Provider Request output,
// attempt = Persist Route + Create Attempt row, httpItem = HTTP node item json.
function vfStepAfterSubmit(request, attempt, httpItem) {
  const http = vfHttpResult(httpItem);
  const normalized = VF_SUBMIT_NORMALIZERS[request.provider_slug](http);
  const submitOutput = {
    accepted: normalized.accepted,
    provider_job_id: normalized.provider_job_id,
    status: normalized.status,
    estimated_cost: request.estimate ? request.estimate.amount : null,
    raw_response: normalized.raw_response,
    poll: normalized.poll || null,
    http_status: http.status_code,
  };
  const common = { worker_id: request.worker_id, job_id: request.job_id, attempt_id: attempt.attempt_id, provider_slug: request.provider_slug, submit: submitOutput };

  if (!normalized.accepted) {
    return Object.assign(common, {
      outcome: 'FAILED',
      fail_payload: vfFailPayload({ job_id: request.job_id, worker_id: request.worker_id, attempt_id: attempt.attempt_id, error: normalized.error, stage: 'submit', raw_response: normalized.raw_response }),
    });
  }
  if (normalized.status === 'SUCCEEDED' && Array.isArray(normalized.files) && normalized.files.length) {
    return Object.assign(common, {
      outcome: 'SUCCEEDED',
      complete_payload: vfCompletePayload({
        job_id: request.job_id,
        attempt_id: attempt.attempt_id,
        worker_id: request.worker_id,
        expected_status: 'PROCESSING',
        job_kind: request.job_kind,
        provider_slug: request.provider_slug,
        provider_job_id: normalized.provider_job_id,
        normalized,
        estimate: request.estimate,
        lineage: request.lineage,
      }),
    });
  }
  return Object.assign(common, {
    outcome: 'WAITING_PROVIDER',
    mark_payload: {
      job_id: request.job_id,
      attempt_id: attempt.attempt_id,
      worker_id: request.worker_id,
      provider_job_id: normalized.provider_job_id,
      submit_result: submitOutput,
    },
  });
}

// ---------------------------------------------------------------------------
// Provider Poll
// ---------------------------------------------------------------------------

// "Build Poll Request": row = Claim Waiting Provider Job row.
function vfStepBuildPoll(row, workerId, nowIso) {
  if (!row || !row.job || !row.job.id) return { outcome: 'NO_JOB' };
  const job = row.job;
  const attempt = row.attempt;
  const base = { worker_id: workerId, job_id: job.id, provider_slug: row.provider_slug, job_kind: job.job_kind };

  if (!attempt || !attempt.id) {
    return Object.assign(base, { outcome: 'FAILED', attempt_id: null, fail_payload: vfFailPayload({ job_id: job.id, worker_id: workerId, attempt_id: null, error: 'ATTEMPT_RECORD_MISSING for provider job ' + job.external_job_id, stage: 'poll' }) });
  }
  base.attempt_id = attempt.id;

  const adapter = row.adapter || {};
  const startedMs = Date.parse(attempt.started_at);
  const maxMinutes = vfNum(adapter.max_poll_minutes) || 30;
  if (Number.isFinite(startedMs) && Date.parse(nowIso) - startedMs > maxMinutes * 60000) {
    return Object.assign(base, {
      outcome: 'FAILED',
      fail_payload: vfFailPayload({ job_id: job.id, worker_id: workerId, attempt_id: attempt.id, error: 'PROVIDER_POLL_TIMEOUT after ' + maxMinutes + ' minutes (provider job ' + job.external_job_id + ')', stage: 'poll' }),
    });
  }

  const inputs = vfResolveInputs(job, row.input_assets);
  const ctx = Object.assign(base, {
    provider_job_id: job.external_job_id,
    estimate: (job.routing_decision && job.routing_decision.cost_estimate) || null,
    lineage: vfLineageFor(inputs),
  });

  if (row.provider_slug === 'fal') {
    const r = vfFalStatusRequest(attempt, row.offer || {});
    return Object.assign(ctx, { outcome: 'POLL', provider_request: { method: 'GET', url: r.url }, fal_response_url: r.response_url });
  }
  if (row.provider_slug === 'kie') {
    return Object.assign(ctx, { outcome: 'POLL', provider_request: vfKieStatusRequest(attempt) });
  }
  return Object.assign(ctx, { outcome: 'FAILED', fail_payload: vfFailPayload({ job_id: job.id, worker_id: workerId, attempt_id: attempt.id, error: 'NO_POLL_ADAPTER for provider ' + row.provider_slug, stage: 'poll' }) });
}

// "Normalize Poll Result": poll = Build Poll Request output. For fal this
// handles the queue status call; vfStepAfterFalResult handles the result call.
function vfStepAfterPoll(poll, httpItem) {
  const http = vfHttpResult(httpItem);
  const n = poll.provider_slug === 'fal' ? vfFalNormalizeStatus(http) : vfKieNormalizePoll(http);
  if (n.needs_result_fetch) {
    return Object.assign({}, poll, { outcome: 'FETCH_RESULT', provider_request: { method: 'GET', url: poll.fal_response_url }, poll_status: n });
  }
  return vfPollOutcome(poll, n);
}

function vfStepAfterFalResult(poll, httpItem) {
  return vfPollOutcome(poll, vfFalNormalizeResult(vfHttpResult(httpItem)));
}

function vfPollOutcome(poll, n) {
  const pollOutput = {
    status: n.status,
    result_urls: n.result_urls || [],
    actual_cost: null,
    error: n.error || null,
    raw_response: n.raw_response,
    credits_consumed: n.credits_consumed == null ? null : n.credits_consumed,
    transient: n.transient === true,
  };
  const base = Object.assign({}, poll, { poll: pollOutput });
  delete base.provider_request;

  if (n.status === 'SUCCEEDED') {
    const complete = vfCompletePayload({
      job_id: poll.job_id,
      attempt_id: poll.attempt_id,
      worker_id: poll.worker_id,
      expected_status: 'WAITING_PROVIDER',
      job_kind: poll.job_kind,
      provider_slug: poll.provider_slug,
      provider_job_id: poll.provider_job_id,
      normalized: n,
      estimate: poll.estimate,
      lineage: poll.lineage,
    });
    pollOutput.actual_cost = complete.actual_cost;
    return Object.assign(base, { outcome: 'SUCCEEDED', complete_payload: complete });
  }
  if (n.status === 'FAILED' || n.status === 'CANCELLED') {
    return Object.assign(base, {
      outcome: n.status,
      fail_payload: vfFailPayload({ job_id: poll.job_id, worker_id: poll.worker_id, attempt_id: poll.attempt_id, error: n.error || 'provider reported ' + n.status, stage: 'poll', raw_response: n.raw_response }),
    });
  }
  return Object.assign(base, {
    outcome: n.status === 'PENDING' ? 'PENDING' : 'RUNNING',
    release_payload: {
      job_id: poll.job_id,
      worker_id: poll.worker_id,
      attempt_id: poll.attempt_id,
      provider_status: n.status,
      warning: n.transient ? n.error : null,
      raw_response: n.raw_response,
    },
  });
}

// ---------------------------------------------------------------------------
// Shared payload builders (consumed by runtime/sql/*.sql)
// ---------------------------------------------------------------------------

function vfCompletePayload(a) {
  const n = a.normalized;
  const estimate = a.estimate || {};
  // fal does not return a per-request charge: the verified offer rate times the
  // requested units is recorded as the charge and labelled as such.
  // Kie returns credits only: USD stays unknown until a verified credit rate exists.
  let actualCost = null;
  let costStatus = 'UNKNOWN';
  if (a.provider_slug === 'fal' && vfNum(estimate.amount) != null) {
    actualCost = vfNum(estimate.amount);
    costStatus = 'OFFER_RATE_X_REQUESTED_UNITS';
  } else if (a.provider_slug === 'kie') {
    costStatus = n.credits_consumed == null ? 'UNKNOWN' : 'KIE_CREDITS_ONLY';
  }
  return {
    job_id: a.job_id,
    attempt_id: a.attempt_id,
    worker_id: a.worker_id,
    expected_status: a.expected_status,
    asset_type: VF_ASSET_TYPE_BY_JOB_KIND[a.job_kind] || 'OTHER',
    storage_provider: a.provider_slug,
    provider_job_id: a.provider_job_id,
    files: (n.files || []).map((f) => Object.assign({}, f, { mime_type: f.mime_type || vfGuessMime(f.url, a.job_kind) })),
    lineage: a.lineage || [],
    actual_cost: actualCost,
    currency: estimate.currency || 'USD',
    cost_status: costStatus,
    cost_quantity: estimate.units == null ? null : estimate.units,
    cost_unit: estimate.unit || null,
    credits_consumed: n.credits_consumed == null ? null : n.credits_consumed,
    raw_response: n.raw_response,
  };
}

function vfFailPayload(a) {
  return {
    job_id: a.job_id,
    worker_id: a.worker_id,
    attempt_id: a.attempt_id || null,
    error: vfTruncate(a.error || 'unknown failure', 1000),
    stage: a.stage,
    raw_response: a.raw_response == null ? null : a.raw_response,
    routing_decision: a.routing_decision || null,
  };
}

// For error outputs of Postgres/HTTP nodes: pull a readable message.
function vfErrorMessage(item) {
  if (!item) return 'unknown error';
  const e = item.error;
  return vfTruncate(item.message || (e && (e.message || e.description)) || (typeof e === 'string' ? e : JSON.stringify(e || item)), 500);
}


// ---- node step ----
return [{ json: vfStepAfterUpload($('After Download').first().json, $input.first().json, Object.assign({}, {"backend":"supabase_storage","path_template":"episodes/{episode_id}/assets/{asset_id}.{ext}","public_read":false,"cache_control":"max-age=31536000"}, $('Build Archive Request').first().json.storage_config || {})) }];

// Video Factory normalized provider contract (v1).
//
// This file and the other provider-adapters/*.js files are plain scripts that
// share one scope. scripts/build-workflows.mjs inlines them into n8n Code
// nodes, and scripts/test-runtime.mjs loads the same text for dry-run tests.
// Do not use require/import here: n8n Code nodes cannot load local modules.
//
// Submit input : provider_model_slug, prompt, negative_prompt, parameters,
//                input_manifest, idempotency_key
// Submit output: accepted, provider_job_id, status, estimated_cost, raw_response
// Poll output  : status (PENDING|RUNNING|SUCCEEDED|FAILED|CANCELLED),
//                result_urls[], actual_cost, error, raw_response
//
// Credentials never appear in any of these objects. HTTP authentication is
// attached by n8n credentials on the HTTP Request nodes.

const VF_CONTRACT_VERSION = '1.0';
const VF_POLL_STATUSES = ['PENDING', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED'];
const VF_UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const VF_ASSET_TYPE_BY_JOB_KIND = {
  IMAGE: 'IMAGE',
  VIDEO: 'VIDEO',
  AUDIO: 'AUDIO',
  TTS: 'VOICE',
  MUSIC: 'MUSIC',
};

const VF_LINEAGE_BY_ROLE = {
  start_frame: 'START_FRAME',
  end_frame: 'END_FRAME',
  reference: 'REFERENCE',
  reference_image: 'REFERENCE',
  reference_video: 'REFERENCE',
  reference_audio: 'AUDIO_SOURCE',
  audio: 'AUDIO_SOURCE',
  edit_source: 'EDIT_SOURCE',
};

function vfIsUuid(value) {
  return typeof value === 'string' && VF_UUID_RE.test(value);
}

function vfRound6(n) {
  return Math.round(n * 1e6) / 1e6;
}

function vfNum(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function vfTruncate(text, max) {
  const s = String(text == null ? '' : text);
  return s.length > max ? s.slice(0, max) + '…' : s;
}

// Resolve input_manifest entries to { role, uri, asset_id } using the
// registered assets loaded from video_factory.assets when an entry only
// carries an asset_id.
function vfResolveInputs(job, inputAssets) {
  const byId = {};
  for (const a of inputAssets || []) byId[a.asset_id] = a;
  const manifest = Array.isArray(job.input_manifest) ? job.input_manifest : [];
  return manifest.map((entry) => {
    const role = String(entry.role || '').toLowerCase();
    const asset = vfIsUuid(entry.asset_id) ? byId[entry.asset_id] : undefined;
    return {
      role,
      uri: entry.uri || entry.url || (asset && asset.uri) || null,
      asset_id: asset ? asset.asset_id : null,
    };
  });
}

function vfInputsByRole(inputs, role) {
  return inputs.filter((i) => i.role === role && i.uri).map((i) => i.uri);
}

// Effective generation parameters: job.parameters win, then shot planning data.
function vfEffectiveParameters(job, shot) {
  const params = Object.assign({}, job.parameters || {});
  if (params.duration_seconds == null && shot && shot.target_duration_seconds != null) {
    params.duration_seconds = vfNum(shot.target_duration_seconds);
  }
  if (params.aspect_ratio == null && shot && shot.aspect_ratio) {
    params.aspect_ratio = shot.aspect_ratio;
  }
  return params;
}

function vfRequestedDuration(params) {
  const d = vfNum(params.duration_seconds != null ? params.duration_seconds : params.duration);
  return d == null ? 5 : d;
}

// Cost estimate from a verified offer. Unknown prices stay unknown: the
// router never invents a price, and an unknown price never beats a known one.
function vfEstimateCost(offer, job, params) {
  const price = vfNum(offer.unit_price);
  const currency = offer.currency || 'USD';
  if (price == null) {
    return { amount: null, units: null, unit: null, currency, status: 'UNKNOWN_PRICE', pricing_basis: offer.pricing_basis };
  }
  let units = null;
  let unit = null;
  switch (offer.pricing_basis) {
    case 'PER_SECOND':
      units = Math.ceil(vfRequestedDuration(params));
      unit = 'second';
      break;
    case 'PER_IMAGE':
      units = Math.max(1, Math.floor(vfNum(params.num_images) || 1));
      unit = 'image';
      break;
    case 'PER_CHARACTER':
      units = String(job.prompt || '').length;
      unit = 'character';
      break;
    case 'PER_REQUEST':
      units = 1;
      unit = 'request';
      break;
    default:
      return { amount: null, units: null, unit: null, currency, status: 'UNSUPPORTED_PRICING_BASIS', pricing_basis: offer.pricing_basis };
  }
  return { amount: vfRound6(price * units), units, unit, currency, status: 'ESTIMATED_FROM_OFFER', pricing_basis: offer.pricing_basis, unit_price: price };
}

function vfGuessMime(url, jobKind) {
  const u = String(url || '').split('?')[0].toLowerCase();
  if (u.endsWith('.mp4')) return 'video/mp4';
  if (u.endsWith('.mov')) return 'video/quicktime';
  if (u.endsWith('.webm')) return 'video/webm';
  if (u.endsWith('.png')) return 'image/png';
  if (u.endsWith('.jpg') || u.endsWith('.jpeg')) return 'image/jpeg';
  if (u.endsWith('.webp')) return 'image/webp';
  if (u.endsWith('.mp3')) return 'audio/mpeg';
  if (u.endsWith('.wav')) return 'audio/wav';
  return { VIDEO: 'video/mp4', IMAGE: 'image/png', TTS: 'audio/mpeg', AUDIO: 'audio/mpeg' }[jobKind] || null;
}

// Lineage rows for a completed job, derived from registered input assets only.
function vfLineageFor(inputs) {
  const seen = new Set();
  const rows = [];
  for (const i of inputs) {
    if (!i.asset_id) continue;
    const rel = VF_LINEAGE_BY_ROLE[i.role] || 'SOURCE';
    const key = i.asset_id + ':' + rel;
    if (seen.has(key)) continue;
    seen.add(key);
    rows.push({ asset_id: i.asset_id, relationship_type: rel });
  }
  return rows;
}

// Normalize an HTTP Request node result (fullResponse + neverError, or an
// error-output item) into { transport_ok, status_code, body, transport_error }.
function vfHttpResult(item) {
  const j = item || {};
  if (typeof j.statusCode === 'number') {
    // n8n puts a non-JSON response body under `data` when fullResponse is on.
    let body = j.body !== undefined ? j.body : j.data;
    if (typeof body === 'string') {
      try { body = JSON.parse(body); } catch (e) { /* keep text */ }
    }
    return { transport_ok: true, status_code: j.statusCode, body, headers: j.headers || {}, transport_error: null };
  }
  const message = (j.error && (j.error.message || j.error.description)) || j.message || 'HTTP request failed before a response was received';
  return { transport_ok: false, status_code: null, body: null, headers: {}, transport_error: vfTruncate(message, 500) };
}

// Strip anything that could carry authentication material before persisting a
// raw provider payload.
function vfSafeRaw(value) {
  const drop = /^(authorization|proxy-authorization|cookie|set-cookie|token|access_token|refresh_token)$/i;
  const walk = (v, depth) => {
    if (depth > 8 || v === null || typeof v !== 'object') return v;
    if (Array.isArray(v)) return v.slice(0, 50).map((x) => walk(x, depth + 1));
    const out = {};
    for (const [k, x] of Object.entries(v)) {
      if (drop.test(k)) continue;
      out[k] = walk(x, depth + 1);
    }
    return out;
  };
  return walk(value, 0);
}

// fal adapter (queue API).
//
// Submit: POST https://queue.fal.run/<queue path>   -> { request_id, status_url, response_url, cancel_url }
// Poll  : GET  status_url                            -> { status: IN_QUEUE | IN_PROGRESS | COMPLETED }
// Result: GET  response_url                          -> model output ({ video } | { images } | { audio })
//
// Request fields were taken from fal's model metadata API
// (GET https://api.fal.ai/v1/models?endpoint_id=...&expand=openapi-3.0) on 2026-09-17.

const VF_FAL_QUEUE_BASE = 'https://queue.fal.run';

// Several verified offers store fal's public endpoint alias. The queue API is
// served from the OpenAPI path below; unmapped keys are used verbatim.
const VF_FAL_QUEUE_PATHS = {
  'minimax/h3-max-turbo/image-to-video': 'fal-ai/minimax-h3-turbo/max-turbo/image-to-video',
  'minimax/h3-max-turbo/text-to-video': 'fal-ai/minimax-h3-turbo/max-turbo/text-to-video',
  'minimax/h3-max/image-to-video': 'fal-ai/minimax-h3-turbo/image-to-video',
  'openai/gpt-image-2.5/sunburst/text-to-image': 'fal-ai/gpt-image-2.5-sunburst',
  'openai/gpt-image-2.5/sunburst/edit': 'fal-ai/gpt-image-2.5-sunburst/edit',
  'bytedance/seedance-2.5/image-to-video': 'fal-ai/seedance-2.5/image-to-video',
  'bytedance/seedance-2.5/reference-to-video': 'fal-ai/seedance-2.5/reference-to-video',
};

function vfFalQueuePath(offer) {
  const key = offer.endpoint_key || offer.provider_model_key;
  return VF_FAL_QUEUE_PATHS[key] || key;
}

function vfIntInRange(value, min, max) {
  const n = vfNum(value);
  return n != null && Number.isInteger(n) && n >= min && n <= max;
}

function vfResolutionToSize(resolution) {
  const m = /^(\d+)x(\d+)$/.exec(String(resolution || ''));
  return m ? { width: Number(m[1]), height: Number(m[2]) } : null;
}

function vfCompact(obj) {
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (v === undefined || v === null) continue;
    if (Array.isArray(v) && v.length === 0) continue;
    out[k] = v;
  }
  return out;
}

// Each mapper: modes it serves, validate(job, params, inputs, offer) -> reason | null,
// body(job, params, inputs, offer) -> provider JSON body.
